// Consolidar todos los datos
const leads = $('Obtener Datos Leads').all();
const voice = $('Obtener Datos Voice').all();
const emails = $('Obtener Datos Email').all();
const analytics = $('Obtener Google Analytics').all();

// Calcular métricas principales
const metrics = {
  // Leads
  totalLeads: leads.length,
  leadsCalientes: leads.filter(l => l.json.fields.Clasificacion === 'Caliente').length,
  leadsTibios: leads.filter(l => l.json.fields.Clasificacion === 'Tibio').length,
  leadsFrios: leads.filter(l => l.json.fields.Clasificacion === 'Frío').length,

  // Comunicaciones
  totalVoiceInteractions: voice.length,
  totalEmailsSent: emails.length,
  emailOpenRate: emails.filter(e => e.json.fields.Abierto).length / emails.length * 100 || 0,

  // Conversiones
  conversionRate: (leads.filter(l => l.json.fields.Estado === 'Convertido').length / leads.length * 100) || 0,

  // Analytics
  totalSessions: analytics.reduce((acc, curr) => acc + (curr.json.sessions || 0), 0),
  totalUsers: analytics.reduce((acc, curr) => acc + (curr.json.activeUsers || 0), 0),

  // Fechas
  fechaInicio: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
  fechaFin: new Date().toISOString().split('T')[0]
};

// Calcular tendencias (comparación con periodo anterior)
const tendencias = {
  leadsGrowth: Math.random() * 40 - 10, // Simulado - debería comparar con periodo anterior
  voiceGrowth: Math.random() * 30 - 5,
  emailGrowth: Math.random() * 25 - 10,
  trafficGrowth: Math.random() * 35 - 15
};

return {
  metrics,
  tendencias,
  rawData: {
    leads: leads.map(l => l.json.fields),
    voice: voice.map(v => v.json.fields),
    emails: emails.map(e => e.json.fields)
  }
};

